describe('Error State - Invalid Input Correction', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should clear error state when user corrects invalid input', () => {
    // Intercept the API call to validate the input
    cy.intercept('POST', '/api/validate-input', {
      statusCode: 400,
      body: { error: 'Input must be a valid email address' }
    }).as('validateInput');

    // Fill in the form with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Input must be a valid email address');

    // Wait for API validation
    cy.wait('@validateInput');

    // Clear the invalid input
    cy.get('[data-testid="email-input"]').clear();

    // Type in a valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Submit the form again
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message is gone
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');
  });

  it('should not clear error state when user submits with invalid input', () => {
    // Intercept the API call to validate the input
    cy.intercept('POST', '/api/validate-input', {
      statusCode: 400,
      body: { error: 'Input must be a valid email address' }
    }).as('validateInput');

    // Fill in the form with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Input must be a valid email address');

    // Wait for API validation
    cy.wait('@validateInput');

    // Attempt to clear the input
    cy.get('[data-testid="email-input"]').clear();

    // Submit the form again with the same invalid input
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message persists
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Input must be a valid email address');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
